// Loader hook: when NEAR_MISS names a copy `.team/near-miss/<n>-<file>`, imports of lib/<file> load the copy,
// and the copy's own relative imports resolve as if it lived in lib/.
import { basename } from 'node:path'
import { pathToFileURL } from 'node:url'

const ROOT = '/root/bench-runs/h5-b31b7a1d'
const copy = process.env.NEAR_MISS
const copyUrl = copy && pathToFileURL(copy).href
const origUrl = copy && pathToFileURL(`${ROOT}/lib/${basename(copy).replace(/^\d+-/, '')}`).href

export async function resolve(specifier, context, next) {
  if (!copy) return next(specifier, context)
  const parentURL = context.parentURL === copyUrl ? origUrl : context.parentURL
  const result = await next(specifier, { ...context, parentURL })
  return result.url === origUrl ? { ...result, url: copyUrl, shortCircuit: true } : result
}

