// Runs the test suite once per near-miss copy (loaded through the hook, lib/ untouched). Prints CAUGHT / SURVIVED.
import { readdirSync, readFileSync } from 'node:fs'
import { spawnSync } from 'node:child_process'

const ROOT = '/root/bench-runs/h5-b31b7a1d'
const dir = `${ROOT}/.team/near-miss`
const only = process.argv[2]
const files = readdirSync(dir).filter(f => f.endsWith('.mjs') && (!only || f === only))
  .sort((a, b) => parseInt(a) - parseInt(b))
for (const f of files) {
